"""Random inputs for run-length encoding: one line of text.

Everything is built out of runs, so the interesting shapes -- a count that
needs two digits, a letter that comes back later, upper and lower case sitting
next to each other -- are guaranteed rather than hoped for.
"""

LETTERS = "abcdefghijklmnopqrstuvwxyz"


def generate(rng, count):
    builders = (_mixed_runs, _no_repeats, _long_run, _mixed_case)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, text, description=""):
    return {"name": name, "stdin": text + "\n", "description": description}


def _runs(rng, alphabet, lengths):
    """Glue runs together, never letting one letter start the next run."""
    text = []
    previous = ""
    for length in lengths:
        letter = rng.choice([c for c in alphabet if c != previous])
        previous = letter
        text.append(letter * length)
    return "".join(text)


def _mixed_runs(rng, index):
    lengths = [rng.randint(1, 4) for _ in range(rng.randint(3, 6))]
    return _case("mixed runs #%d" % index, _runs(rng, LETTERS[:8], lengths))


def _no_repeats(rng, index):
    lengths = [1] * rng.randint(4, 8)
    return _case("no repeats #%d" % index, _runs(rng, LETTERS[:10], lengths),
                 "Every run is one character long, and each still gets a count.")


def _long_run(rng, index):
    lengths = [rng.randint(1, 3), rng.randint(10, 15), rng.randint(1, 3)]
    return _case("a run past nine #%d" % index, _runs(rng, LETTERS[:6], lengths),
                 "One run is longer than nine, so its count needs more than "
                 "one digit and must not split into two runs.")


def _mixed_case(rng, index):
    lengths = [rng.randint(1, 3) for _ in range(rng.randint(4, 7))]
    return _case("case is significant #%d" % index, _runs(rng, "aAbBcC", lengths),
                 "Upper and lower case are different characters.")
